const {chromium}=require('playwright');const fs=require('fs');const crypto=require('crypto');
const unescape=s=>String(s||'').replace(/&amp;/g,'&').replace(/&quot;/g,'"').replace(/&#39;/g,"'");
const attrs=s=>Object.fromEntries([...s.matchAll(/([\w:-]+)\s*=\s*["']([^"']*)["']/g)].map(m=>[m[1],unescape(m[2])]));
const reject=/favicon|logo|weather|menu-image|maps\.google|facebook\.com\/tr|banner-footer|footer-image|icons?\//i;
(async()=>{
 const browser=await chromium.launch({headless:true});const results=[];
 let cursor=0;
 async function worker(){
  const context=await browser.newContext();const page=await context.newPage();
  while(cursor<inputs.length){
   const input=inputs[cursor++];const result={id:input.id,pages:[],images:[],bookings:[]};
   const candidates=[];if(input.image&&!reject.test(input.image))candidates.push({url:input.image,source:input.url,origin:'previous original listing asset'});
   const sources=[input.url,...input.secondary];
   for(let i=0;i<sources.length&&i<4;i++){
    const source=sources[i];
    try{
     const response=await context.request.get(source,{timeout:12000});const html=await response.text();
     const title=unescape((html.match(/<title[^>]*>([\s\S]*?)<\/title>/i)||[])[1]||'');
     result.pages.push({url:source,status:response.status(),title});
     if(!response.ok())continue;
     for(const tag of html.match(/<meta\b[^>]*>/gi)||[]){const a=attrs(tag);if((a.property==='og:image'||a.name==='twitter:image')&&a.content&&!reject.test(a.content))candidates.push({url:new URL(a.content,source).href,source,origin:'organiser listing social image',alt:title});}
     for(const u of html.match(/https?:[^\s"'<>\\]+\.(?:png|jpe?g|webp)(?:[^\s"'<>\\]*)/gi)||[]){if(/featured|\/atdw\/|\/wp-content\/|\/events\/|\/library\//i.test(u)&&!reject.test(u))candidates.push({url:unescape(u),source,origin:'event page image reference'});}
     for(const tag of html.match(/<img\b[^>]*>/gi)||[]){const a=attrs(tag);const u=a.src||a['data-src'];if(u&&!reject.test(u)&&!/^data:/.test(u))candidates.push({url:new URL(u,source).href,source,origin:'organiser page img',alt:a.alt||''});}
     for(const m of html.matchAll(/<a\b([^>]*)>([\s\S]*?)<\/a>/gi)){const a=attrs(m[1]);if(a.href&&/eventbrite\.|humanitix\./i.test(a.href)){const u=new URL(a.href,source).href;result.bookings.push({url:u,label:unescape(m[2].replace(/<[^>]*>/g,'')).trim().slice(0,100)});if(sources.length<4&&!sources.includes(u))sources.push(u);}}
    }catch(e){result.pages.push({url:source,error:e.message});}
   }
   const seen=new Set();
   for(const candidate of candidates){
    if(result.images.filter(x=>x.decoded).length>=2)break;
    if(seen.has(candidate.url))continue;seen.add(candidate.url);
    if(seen.size>8)break;
    const item={...candidate};
    try{
     const response=await context.request.get(candidate.url,{headers:{Referer:candidate.source},timeout:10000});const type=response.headers()['content-type']||'';item.status=response.status();item.type=type;
     if(response.ok()&&/^image\//.test(type)){
      const bytes=await response.body();await page.goto('about:blank');await page.setContent('<img src="data:'+type.split(';')[0]+';base64,'+bytes.toString('base64')+'">');await page.locator('img').evaluate(i=>i.decode());
      Object.assign(item,await page.locator('img').evaluate(i=>({width:i.naturalWidth,height:i.naturalHeight})));item.decoded=item.width>=300&&item.height>=200;item.sha256=crypto.createHash('sha256').update(bytes).digest('hex');
      if(item.decoded){await page.setContent('<img src="'+candidate.url.replace(/&/g,'&amp;').replace(/"/g,'&quot;')+'">');await page.locator('img').evaluate(i=>new Promise(r=>{if(i.complete)r();else{i.onload=r;i.onerror=r;setTimeout(r,5000);}}));item.hotlinkRendered=await page.locator('img').evaluate(i=>i.naturalWidth>0);}
     }
    }catch(e){item.error=e.message;}
    result.images.push(item);
   }
   results.push(result);console.log('HELD_IMAGE_AUDIT '+JSON.stringify(result));
  }
  await context.close();
 }
 await Promise.all([worker(),worker(),worker(),worker()]);await browser.close();fs.writeFileSync('held-image-audit.json',JSON.stringify(results,null,2));
 console.log('HELD_AUDIT_SUMMARY '+JSON.stringify({count:results.length,withDecodedAssets:results.filter(r=>r.images.some(i=>i.decoded)).length}));
})();
